      if(catalog)catalog.onchange=()=>{const saved=ST.exclusiveProducts.find(value=>value.id===catalog.value);row.dataset.exclusiveCatalogId=saved?.id||'';if(!saved){name.readOnly=false;name.value='';row.dataset.exclusiveImage='';row.querySelector('.shipping-editor-photo img').src=exclusiveImage(null);return name.focus()}name.readOnly=true;name.value=saved.name;row.dataset.exclusiveImage=saved.image_path||'';row.querySelector('.shipping-editor-photo img').src=exclusiveImage(saved.image_path);if(saved.default_color_id)color.value=`color:${saved.default_color_id}`;units.value=saved.default_listing_units||100;preset.value=[50,100,200].includes(n(units.value))?String(units.value):'custom';type.value=saved.default_volume_type||'kit';notes.value=saved.default_notes||'';updateColorField(color);updateSummary()};
      color.onchange=()=>{if(color.value==='new')return openColorCombinationEditor(color);updateColorField(color)};
      preset.onchange=()=>{if(preset.value!=='custom')units.value=preset.value;units.focus();updateSummary()};
      const file=row.querySelector('[data-exclusive-photo]');if(file)file.onchange=()=>{const selected=file.files?.[0];if(!selected)return;if(selected.size>2097152){file.value='';return alert('A foto deve ter no máximo 2 MB.')}if(!['image/jpeg','image/png','image/webp'].includes(selected.type)){file.value='';return alert('Use uma imagem JPG, PNG ou WebP.')}row.querySelector('.shipping-editor-photo img').src=URL.createObjectURL(selected)};
